# -*- coding: utf-8 -*-
# (speaker, italian, korean); speaker None => stage direction, "#" => scene heading (neither is a turn)
F, MA, GN, R, M, C = "Filippo", "Marisa", "Gianni", "Renzo", "Matteo", "Chiara"
D = [
("#", "Scena 1 — Giovedì 30 gennaio, ore 7.45. Laboratorio, linea di cucitura", "장면 1 — 1월 30일 목요일 오전 7시 45분. 공방, 재봉 라인"),
(None, "Le macchine da cucire non sono ancora accese. Marisa Conti, trent'anni di linea, sistema i rocchetti di filo. Gianni Lotti, ventotto anni, legge qualcosa sul telefono. Renzo passa con un rotolo di pelle sotto il braccio.", "재봉틀은 아직 켜지지 않았다. 라인에서 30년을 일한 마리사 콘티가 실패를 정리한다. 스물여덟 살 잔니 로티는 휴대폰으로 뭔가를 읽고 있다. 렌초가 가죽 한 롤을 옆구리에 끼고 지나간다."),
(GN, "Renzo, ce l'hai un minuto?", "렌초 아저씨, 잠깐 시간 있어요?"),
(R, "Per te anche due. Che c'è, Gianni? Hai la faccia di uno che non ha dormito.", "너한텐 2분도 있지. 왜, 잔니? 잠 못 잔 얼굴이네."),
(GN, "Ho letto sul gruppo di Scandicci che due laboratori hanno messo la gente in cassa integrazione. Tutti e due lavorano per la Maison.", "스칸디치 단톡방에서 봤는데, 공방 두 곳이 사람들을 휴업 수당으로 돌렸대요. 둘 다 메종 일을 하는 데예요."),
(MA, "E qui da noi si dice che la Maison ha tagliato il quaranta per cento. Lo sanno anche i muri.", "그리고 우리 쪽에선 메종이 40%를 깎았다는 말이 돌아. 벽도 다 알아."),
(R, "I muri parlano tanto, Marisa. Ma non firmano le lettere.", "벽은 말이 많지, 마리사. 하지만 편지에 서명은 안 해."),
(MA, "Allora dicci tu. È vero o no?", "그럼 아저씨가 말해 줘요. 사실이에요, 아니에요?"),
(R, "Io so cucire. Le cifre le sa il direttore. Chiedetele a lui.", "난 바느질할 줄만 알아. 숫자는 사장님이 알지. 사장님한테 물어봐."),
(GN, "È quello che faremo. Alle nove. L'abbiamo chiesto noi l'incontro.", "그럴 거예요. 9시에요. 회의는 우리가 요청했어요."),
(R, "Bravi. Ma andateci con le domande, non con le sentenze.", "잘했다. 하지만 판결 말고 질문을 들고 가라."),
(GN, "E se le risposte non ci piacciono?", "답이 마음에 안 들면요?"),
(R, "Allora fate altre domande. La rabbia, dopo, si trova sempre.", "그럼 다른 질문을 해. 화는 나중에 얼마든지 낼 수 있어."),
(None, "La porta del laboratorio si apre. Entra Filippo, giacca e cravatta, una cartellina in mano. Le teste si girano.", "공방 문이 열린다. 재킷과 넥타이 차림의 필리포가 서류철을 들고 들어온다. 고개들이 돌아간다."),
(F, "Buongiorno a tutti. Marisa, Gianni, l'incontro è confermato alle nove. Ma prima volevo passare di qua.", "다들 좋은 아침입니다. 마리사, 잔니, 회의는 9시로 확정이에요. 그런데 그 전에 여기 들르고 싶었어요."),
(MA, "Per vedere se ci siamo ancora?", "우리가 아직 있나 보려고요?"),
(F, "Per guardarvi in faccia prima di parlare di numeri.", "숫자 얘기하기 전에 얼굴 보려고요."),
(MA, "Le facce le conosci, Filippo. Ti abbiamo visto crescere qui dentro.", "얼굴은 알잖아, 필리포. 우리가 여기서 너 크는 거 다 봤는데."),
(F, "Appunto. Per questo non vi mando una circolare.", "그러니까요. 그래서 공문 대신 직접 온 거예요."),

("#", "Scena 2 — Ore 9.00. Sala riunioni", "장면 2 — 오전 9시. 회의실"),
(GN, "Allora, direttore. Andiamo al sodo. La Maison ha tagliato gli ordini. Di quanto?", "그럼, 사장님. 본론으로 가죠. 메종이 주문을 깎았죠. 얼마나요?"),
(F, "La loro prima richiesta è il quaranta per cento sulla primavera-estate. Stiamo trattando per portarla al trenta. Il sette febbraio vado a Parigi.", "처음 요구는 봄·여름 시즌 40%예요. 30%로 낮추려고 협상 중이고요. 2월 7일에 파리에 갑니다."),
(GN, "Trenta o quaranta, in persone quante sono?", "30이든 40이든, 사람으로 치면 몇 명이에요?"),
(F, "Se resta al quaranta, a marzo avremmo lavoro per circa sessanta persone in meno. Se scende al trenta, una quarantina.", "40%로 남으면 3월에 약 60명분 일이 줄어요. 30%로 내려가면 마흔 명 정도요."),
(MA, "Quaranta persone. Io in quella linea ho trenta colleghe. Me le conti tu, quali sono le quaranta?", "마흔 명이라. 내 라인에만 동료가 서른이야. 그 마흔 명이 누군지 네가 세어 줄래?"),
(F, "Nessuno ha fatto liste, Marisa. E nessuno le farà.", "아무도 명단을 만든 적 없어요, 마리사. 앞으로도 안 만들 거고요."),
(GN, "Ho paura che le liste si facciano da sole, direttore. Prima la cassa integrazione, poi i contratti a termine che non si rinnovano, poi qualcuno che si licenzia perché ha capito l'aria.", "명단은 저절로 만들어질까 봐 겁나요, 사장님. 처음엔 휴업 수당, 다음엔 갱신 안 되는 계약직, 그다음엔 분위기 파악하고 스스로 나가는 사람."),
(F, "Capisco la paura. Ma domenica, a tavola, mia madre l'ha detto: nessuno va in cassa integrazione. E in questa famiglia, quello che si dice a tavola vale come un contratto.", "그 두려움은 이해해요. 하지만 일요일에 어머니가 식탁에서 말씀하셨어요. 아무도 휴업 수당으로 보내지 않는다고요. 이 집안에선 식탁에서 한 말은 계약이나 마찬가지예요."),
(GN, "Con tutto il rispetto per la signora Graziella, una tavola non è un accordo sindacale.", "그라치엘라 회장님께는 송구하지만, 식탁은 노사 합의가 아니에요."),
(MA, "Gianni...", "잔니…"),
(GN, "No, Marisa, lo dico. Noi rappresentiamo duecentocinquanta persone. Ci servono impegni scritti, non promesse di famiglia.", "아니에요, 마리사. 말할래요. 우린 250명을 대표해요. 집안 약속 말고 서면 약속이 필요해요."),
(F, "È giusto. E vi dirò di più: anch'io preferisco le cose scritte. Ma prima devo sapere che cosa scrivere.", "맞는 말이에요. 그리고 더 말하자면, 저도 서면이 좋아요. 그런데 먼저 무엇을 쓸지 알아야 해요."),
(MA, "E cosa scriveresti, oggi, se dovessi farlo?", "오늘 써야 한다면 뭐라고 쓸 건데?"),
(F, "Che fino al trenta aprile non ci sarà nessun licenziamento e nessuna cassa integrazione. Questo posso firmarlo stamattina.", "4월 30일까지 해고도, 휴업 수당도 없다고요. 그건 오늘 아침에 서명할 수 있어요."),
(MA, "Il trenta aprile. Tre mesi.", "4월 30일. 석 달이네."),
(F, "Tre mesi in cui nessuno resta a casa. Lo so che non è per sempre. Ma è scritto.", "석 달 동안 아무도 집에 있지 않아요. 영원한 게 아니라는 건 알아요. 하지만 문서로 남는 거예요."),
(GN, "E gli straordinari? Chi resta sulle linee della Maison dovrà correre il doppio per coprire chi si sposta?", "잔업은요? 메종 라인에 남는 사람들이 옮겨 간 사람 몫까지 두 배로 뛰어야 하는 거예요?"),
(F, "No. Le linee della Maison avranno meno ordini, non meno persone. Nessuno farà straordinari per coprire un collega.", "아니요. 메종 라인은 주문이 줄어드는 거지 사람이 줄어드는 게 아니에요. 동료 몫을 메우려고 잔업하는 사람은 없을 거예요."),
(MA, "Questo scrivilo, Filippo. Le ragazze della mia linea hanno figli piccoli. Alle cinque e mezza devono essere all'asilo.", "그것도 적어, 필리포. 우리 라인 사람들은 애들이 어려. 5시 반엔 어린이집에 가 있어야 해."),
(F, "Lo scrivo. Parola per parola.", "적을게요. 한 마디도 빼지 않고."),
(GN, "E dal primo maggio?", "5월 1일부터는요?"),
(F, "Dal primo maggio dipende da quello che riusciamo a fare a febbraio e marzo.", "5월 1일부터는 2월과 3월에 우리가 뭘 해내느냐에 달렸어요."),
(GN, "Cioè dipende dalla Maison. Come sempre.", "그러니까 메종에 달렸다는 거네요. 늘 그렇듯이."),
(F, "No. Questa volta no. O almeno, non solo.", "아니요. 이번엔 아니에요. 적어도 메종만은 아니에요."),
(MA, "Spiegati.", "설명해 봐."),
(F, "Le ore di lavoro che la Maison non ci compra, vogliamo usarle per noi. Per il nostro marchio. Ma su questo non sono io la persona giusta per parlare. Posso farli entrare?", "메종이 사 가지 않는 작업 시간을 우리 걸 위해 쓰고 싶어요. 우리 브랜드를 위해서요. 그런데 이 얘기는 제가 할 사람이 아니에요. 들어오라고 해도 될까요?"),
(GN, "Chi?", "누구를요?"),
(F, "Mio fratello e mia sorella. Sono qui fuori da dieci minuti.", "제 동생들이요. 10분째 밖에 있어요."),
(MA, "(alza le sopracciglia) Tutti e tre insieme nella stessa stanza? Allora è proprio grave.", "(눈썹을 치켜올리며) 셋이 한 방에 같이? 그럼 정말 심각하네."),
(None, "Filippo apre la porta. Entrano Chiara, con una borsa campione sotto il braccio, e Matteo, con il portatile.", "필리포가 문을 연다. 샘플 가방을 옆구리에 낀 키아라와 노트북을 든 마테오가 들어온다."),

("#", "Scena 3 — Ore 9.40. Sala riunioni, la proposta", "장면 3 — 오전 9시 40분. 회의실, 제안"),
(M, "Buongiorno. Marisa, ti ricordi di me? Mi hai insegnato a fare il punto sellaio quando avevo otto anni.", "안녕하세요. 마리사 아주머니, 저 기억하세요? 여덟 살 때 새들 스티치 가르쳐 주셨잖아요."),
(MA, "Mi ricordo che ti sei bucato un dito e hai pianto per un'ora.", "네가 손가락 찔려서 한 시간 동안 운 건 기억나."),
(M, "Ecco. Oggi cerco di non piangere. (apre il portatile) Vi faccio vedere una cosa in due minuti.", "그렇죠. 오늘은 안 울어 볼게요. (노트북을 열며) 2분만 뭐 좀 보여 드릴게요."),
(C, "Prima la borsa, Matteo. I numeri dopo. Loro le borse le capiscono prima dei numeri.", "가방 먼저, 마테오. 숫자는 나중에. 이분들은 숫자보다 가방을 먼저 알아봐."),
(None, "Chiara posa la borsa sul tavolo. Marisa la prende, la gira, guarda le cuciture all'interno.", "키아라가 가방을 테이블에 내려놓는다. 마리사가 들어서 돌려 보고, 안쪽 바느질을 들여다본다."),
(MA, "Questa l'ha fatta Renzo.", "이건 렌초 아저씨가 만들었네."),
(C, "L'abbiamo fatta io e Renzo. Il disegno è mio, le mani sono sue.", "저랑 렌초 아저씨가 같이 만들었어요. 디자인은 제 거고, 손은 아저씨 거예요."),
(MA, "Si vede. Il punto è più fitto di quello della Maison. E la costa è tinta a mano.", "티가 나. 땀이 메종 것보다 촘촘해. 그리고 가장자리도 손으로 칠했고."),
(GN, "Bella. Ma una borsa non paga quaranta stipendi.", "예쁘네요. 하지만 가방 하나로 월급 마흔 명분을 못 줘요."),
(M, "Una no. Trecento sì, per cominciare. Una buyer di Seul vuole un ordine pilota per la primavera. Se va bene, a settembre diventano milleduecento l'anno.", "하나로는 안 되죠. 300개면 시작은 돼요. 서울 바이어가 봄 시즌 시범 주문을 원해요. 잘되면 9월부터 연 1,200개가 돼요."),
(GN, "Milleduecento borse. E quante ore sono?", "가방 1,200개라. 그게 몇 시간이에요?"),
(C, "Questa richiede circa due ore e mezza di lavoro. Più del doppio di un modello della Maison, perché ci sono più passaggi a mano.", "이건 작업 시간이 두 시간 반쯤 걸려요. 메종 모델의 두 배가 넘어요. 손으로 하는 공정이 더 많아서요."),
(M, "Milleduecento borse per due ore e mezza fanno tremila ore. Più l'online, più i dodici negozi in Toscana, che possiamo rifornire meglio.", "1,200개 곱하기 두 시간 반이면 3,000시간이에요. 거기에 온라인, 그리고 더 잘 채워 줄 수 있는 토스카나 매장 열두 곳."),
(GN, "Tremila ore l'anno sono neanche due persone a tempo pieno. Non quaranta.", "연 3,000시간이면 정규직 두 명분도 안 돼요. 마흔 명이 아니라."),
(M, "(pausa) Hai fatto il conto più in fretta di me.", "(잠시 멈추고) 저보다 계산이 빠르시네요."),
(GN, "Faccio i turni da dieci anni. Le ore le so contare.", "교대 근무 10년째예요. 시간은 셀 줄 알아요."),
(C, "Gianni ha ragione. Quest'anno il marchio non può assorbire quaranta persone. Ma può assorbire il primo colpo.", "잔니 말이 맞아요. 올해 브랜드가 마흔 명을 다 흡수할 순 없어요. 하지만 첫 충격은 받아 낼 수 있어요."),
(F, "E c'è un'altra cosa. Mentre facciamo le borse nostre, formiamo la gente sui passaggi a mano. Se la Maison torna a ordinare, avremo più persone capaci di tutto il ciclo.", "그리고 하나 더 있어요. 우리 가방을 만드는 동안 사람들을 손 공정으로 교육하는 거예요. 메종이 다시 주문을 늘리면 전 공정을 다룰 줄 아는 사람이 더 많아지는 거죠."),
(R, "(dalla porta) Posso dire una cosa?", "(문가에서) 한마디 해도 될까?"),
(F, "Renzo? Da quanto sei lì?", "렌초 아저씨? 언제부터 거기 계셨어요?"),
(R, "Dalla borsa. Quando la borsa è mia, ascolto.", "가방 얘기부터. 내 가방이면 듣게 되지."),
(MA, "Di', Renzo.", "말해요, 아저씨."),
(R, "Io ho settantadue anni e, se Dio vuole, ancora qualche anno di mani buone. In quegli anni posso insegnare il cucito a mano a dieci persone. Forse a dodici, se non sono teste dure come Matteo.", "난 일흔둘이고, 하느님이 허락하시면 아직 몇 년은 손이 쓸 만해. 그 몇 년 동안 열 명한테 손바느질을 가르칠 수 있어. 마테오처럼 고집불통만 아니면 열두 명도."),
(M, "Grazie, Renzo.", "고마워요, 아저씨."),
(R, "Ma voglio scegliere io chi. E voglio un tavolo tutto per noi, vicino alla finestra. La luce serve.", "그런데 누군지는 내가 고르고 싶어. 그리고 창가에 우리만 쓰는 작업대가 하나 필요해. 빛이 있어야 하니까."),
(C, "Il tavolo vicino alla finestra ce l'ha il controllo qualità.", "창가 작업대는 품질 검사팀이 쓰는데요."),
(F, "Allora il controllo qualità si sposta. Scrivilo, Matteo.", "그럼 품질 검사팀이 옮기면 되죠. 적어, 마테오."),
(GN, "Un momento. Mi sembra tutto bello, ma io ci sento una trappola.", "잠깐만요. 다 좋아 보이는데, 저는 함정 냄새가 나요."),
(F, "Quale?", "어떤 함정이요?"),
(GN, "Spostate la gente sul marchio, poi il marchio non vende, e a giugno ci dite che non c'è più lavoro né per la Maison né per voi. E a quel punto la colpa è nostra perché abbiamo detto sì.", "사람들을 브랜드 쪽으로 옮겼는데 브랜드가 안 팔리면, 6월에 와서 메종 일도 없고 브랜드 일도 없다고 하겠죠. 그때 가서는 우리가 '예'라고 했으니 우리 탓이 되고요."),
(MA, "Non è una trappola, Gianni. È un rischio. È diverso.", "함정이 아니야, 잔니. 위험이야. 그건 달라."),
(GN, "Per chi perde il posto, non è diverso.", "일자리를 잃는 사람한텐 다를 게 없어요."),
(F, "Allora mettiamolo per iscritto. Il rischio lo prende l'azienda, non voi.", "그럼 서면으로 남깁시다. 위험은 회사가 지는 거지, 여러분이 지는 게 아니라고."),
(GN, "In che modo?", "어떤 식으로요?"),
(F, "Primo: nessun licenziamento e nessuna cassa integrazione fino al trenta aprile, qualunque cosa succeda a Parigi.", "첫째. 파리에서 무슨 일이 생기든 4월 30일까지 해고도 휴업 수당도 없다."),
(GN, "Questo l'hai già promesso. E il secondo?", "그건 아까 약속했잖아요. 둘째는요?"),
(F, "Secondo: chi va a lavorare sulla linea Corsini lo fa su base volontaria, con la stessa paga e la stessa qualifica. E può tornare indietro quando vuole.", "둘째. 코르시니 라인으로 가는 사람은 자원해서 가고, 급여와 등급은 그대로다. 그리고 원할 때 언제든 돌아올 수 있다."),
(MA, "E terzo?", "그리고 셋째는?"),
(F, "Terzo: a fine aprile ci rivediamo qui, con i numeri veri. Quelli di Parigi e quelli di Seul. E decidiamo insieme.", "셋째. 4월 말에 여기서 진짜 숫자를 들고 다시 만난다. 파리 숫자랑 서울 숫자. 그리고 같이 결정한다."),
(GN, "« Insieme » vuol dire che il nostro parere conta, o che ci informate?", "'같이'라는 게 우리 의견이 반영된다는 거예요, 아니면 통보한다는 거예요?"),
(F, "Vuol dire che se non siete d'accordo, me lo dite davanti a mia madre. La domenica.", "동의하지 않으면 우리 어머니 앞에서 그렇게 말해도 된다는 뜻이에요. 일요일에요."),
(MA, "(ride) Questa è una minaccia, non un impegno.", "(웃으며) 그건 약속이 아니라 협박이네."),
(C, "Per mio fratello è la stessa cosa.", "우리 오빠한텐 그게 같은 거예요."),
(GN, "(dopo una pausa) Va bene. Ma voglio vedere il foglio firmato prima di dirlo ai colleghi.", "(잠시 뒤) 좋아요. 하지만 동료들한테 말하기 전에 서명된 문서를 보고 싶어요."),
(F, "Lo avrai entro mezzogiorno. Lo scrive Matteo, lo controlla Lorenzo e lo firmo io.", "정오까지 줄게요. 마테오가 쓰고, 로렌초가 검토하고, 제가 서명할게요."),
(M, "E lo fa leggere anche a Renzo. Così è sicuro che dentro non ci sono parole da banca.", "그리고 렌초 아저씨한테도 읽어 보게 할게요. 그래야 안에 은행 말투가 없는 게 확실하니까."),
(R, "Io leggo piano. Ma leggo tutto.", "난 천천히 읽어. 하지만 전부 읽지."),

("#", "Scena 4 — Ore 12.10. Corridoio davanti al laboratorio", "장면 4 — 오후 12시 10분. 공방 앞 복도"),
(None, "Gianni esce dall'ufficio con un foglio firmato in mano. Filippo lo raggiunge nel corridoio.", "잔니가 서명된 종이를 들고 사무실에서 나온다. 필리포가 복도에서 그를 따라잡는다."),
(F, "Gianni. Un attimo.", "잔니. 잠깐만요."),
(GN, "Direttore.", "사장님."),
(F, "Lascia stare « direttore ». Volevo dirti che avevi ragione, sulle ore. Due persone, non quaranta.", "'사장님'은 됐어요. 시간 얘기는 잔니 말이 맞았다고 말하고 싶었어요. 마흔 명이 아니라 두 명."),
(GN, "Lo so che avevo ragione. Il problema è che avevate ragione anche voi.", "제가 맞았다는 건 알아요. 문제는 그쪽도 맞았다는 거죠."),
(F, "Cioè?", "무슨 말이에요?"),
(GN, "Se restiamo fermi ad aspettare Parigi, fra due anni siamo di nuovo qui. Mio padre lavorava in un laboratorio a Prato. Ha chiuso così: aspettando.", "가만히 파리만 기다리면 2년 뒤에 또 여기 있을 거예요. 우리 아버지가 프라토의 공방에서 일했어요. 그렇게 문을 닫았어요. 기다리다가."),
(F, "Non lo sapevo.", "몰랐어요."),
(GN, "Non me l'avete mai chiesto. Comunque, il foglio lo porto in assemblea alle due. Se passa, il primo volontario sono io.", "물어본 적이 없으니까요. 아무튼 이 종이는 2시 총회에 가져갈게요. 통과되면 첫 번째 자원자는 저예요."),
(F, "Tu? Pensavo che fossi il più contrario.", "잔니가요? 제일 반대하는 줄 알았는데."),
(GN, "Sono contrario alle sorprese, non al lavoro. E poi voglio imparare da Renzo prima che vada in pensione. Dicono che sta per scegliere i suoi dieci.", "전 깜짝 놀랄 일에 반대하는 거지, 일에 반대하는 게 아니에요. 그리고 렌초 아저씨 은퇴하기 전에 배우고 싶어요. 열 명을 곧 고를 거라던데요."),
(F, "Allora sbrigati. Ha detto che non vuole teste dure.", "그럼 서둘러요. 고집불통은 싫다고 하셨으니까."),
(GN, "(sorride per la prima volta) Il che, in questa azienda, esclude metà della famiglia Corsini.", "(처음으로 웃으며) 그 말은, 이 회사에선 코르시니 가족 절반이 빠진다는 얘기네요."),
(None, "Gianni si allontana verso il laboratorio.", "잔니가 공방 쪽으로 멀어진다."),

("#", "Scena 5 — Ore 14.00. Mensa, assemblea dei lavoratori", "장면 5 — 오후 2시. 구내식당, 노동자 총회"),
(None, "Duecento persone tra i tavoli della mensa. Filippo resta in piedi in fondo, vicino alla porta. Marisa sale su una sedia con il foglio in mano.", "구내식당 테이블 사이에 이백 명이 모였다. 필리포는 맨 뒤 문 옆에 서 있다. 마리사가 종이를 들고 의자 위에 올라선다."),
(MA, "Allora. Silenzio, per favore. Vi leggo l'accordo così com'è, senza commenti. I commenti dopo.", "자. 조용히 해 주세요. 합의문을 있는 그대로, 해설 없이 읽을게요. 해설은 나중에."),
(GN, "E dopo ne avremo tanti, di commenti. Vi conosco.", "그리고 해설은 나중에 엄청 많을 거예요. 여러분 다 알아요."),
(MA, "Punto uno: fino al trenta aprile nessun licenziamento e nessuna cassa integrazione, qualunque cosa succeda a Parigi.", "첫째. 파리에서 무슨 일이 생기든 4월 30일까지 해고도 휴업 수당도 없다."),
(None, "Un mormorio attraversa la mensa. Qualcuno applaude, qualcuno incrocia le braccia.", "웅성거림이 식당을 가로지른다. 박수를 치는 사람도 있고, 팔짱을 끼는 사람도 있다."),
(GN, "Lasciatela finire! Le domande dopo.", "끝까지 읽게 해 주세요! 질문은 나중에."),
(MA, "Punto due: chi passa alla linea Corsini lo fa da volontario, stessa paga, stessa qualifica, e può tornare quando vuole. Nessuno fa straordinari per coprire i colleghi.", "둘째. 코르시니 라인으로 가는 사람은 자원자로 가고, 급여도 등급도 그대로이며, 원할 때 돌아올 수 있다. 동료 몫을 메우려고 잔업하는 사람은 없다."),
(GN, "E vale anche per i contratti a termine. L'abbiamo chiesto noi.", "기간제 계약직한테도 똑같이 적용돼요. 우리가 요구한 거예요."),
(MA, "Punto tre: a fine aprile ci rivediamo con i numeri di Parigi e di Seul, e si decide insieme.", "셋째. 4월 말에 파리와 서울 숫자를 들고 다시 만나 함께 결정한다."),
(None, "Una voce dal fondo, una donna con il grembiule della linea di taglio.", "뒤쪽에서 목소리가 들린다. 재단 라인 앞치마를 두른 여자다."),
("Operaia", "E Seul che c'entra? Noi facciamo borse per Parigi da vent'anni!", "서울이 무슨 상관이에요? 우린 20년 동안 파리 가방을 만들어 왔다고요!"),
(GN, "C'entra perché Parigi ci ha tolto il quaranta per cento. E Seul ce ne può ridare un pezzo. Piccolo, ma nostro.", "상관있어요. 파리가 우리한테서 40%를 빼 갔으니까요. 서울이 그중 한 조각을 돌려줄 수 있어요. 작지만 우리 거예요."),
("Operaia", "E chi ci va, alla linea nuova?", "그럼 새 라인엔 누가 가는데요?"),
(R, "(si alza dal tavolo vicino alla cucina) Il primo è Gianni, l'ha chiesto lui. Gli altri li scelgo io. E scelgo chi ha pazienza, non chi ha fretta. Le borse fatte in fretta tornano indietro.", "(주방 옆 테이블에서 일어나며) 첫 번째는 잔니야, 본인이 원했으니까. 나머지는 내가 골라. 그리고 난 서두르는 사람이 아니라 참을성 있는 사람을 골라. 서둘러 만든 가방은 돌아오거든."),
("Operaia", "E se la linea nuova non vende?", "새 라인이 안 팔리면요?"),
(MA, "Allora il rischio è dell'azienda. È scritto. L'ha firmato il direttore stamattina.", "그럼 위험은 회사가 지는 거예요. 적혀 있어요. 오늘 아침에 사장님이 서명했어요."),
(None, "Le teste si girano verso il fondo della mensa. Filippo, vicino alla porta, alza appena la mano.", "고개들이 식당 뒤쪽으로 돌아간다. 문 옆의 필리포가 손을 살짝 든다."),
(F, "È scritto. E se non lo rispetto, venite a dirmelo la domenica. Mia madre apparecchia anche per voi.", "적혀 있어요. 제가 안 지키면 일요일에 와서 말하세요. 우리 어머니가 여러분 자리까지 차려 주실 테니까."),
(None, "Una risata, poi un'altra. La tensione si scioglie.", "웃음이 하나, 또 하나 터진다. 긴장이 풀린다."),
(MA, "Allora votiamo. Chi è a favore dell'accordo alzi la mano.", "그럼 투표합시다. 합의에 찬성하는 사람은 손을 드세요."),
(GN, "(conta) Centottanta... centonovanta. Chi è contrario?", "(세면서) 180… 190. 반대하는 사람?"),
(MA, "Sei. Astenuti quattro. L'accordo passa.", "여섯 명. 기권 네 명. 합의 통과."),
(None, "Mentre la mensa si svuota, Filippo guarda dalla finestra. Nel laboratorio deserto, Renzo sposta da solo un tavolo verso la luce.", "식당이 비어 가는 동안 필리포가 창밖을 본다. 텅 빈 공방에서 렌초가 혼자 작업대를 빛 쪽으로 옮기고 있다."),
]

